+#include <gkyl_gen_miller_eqdsk.h>
+#include <gkyl_alloc.h>
+
+#include <float.h>
+#include <math.h>
+#include <stdint.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include <unistd.h>
+
+enum { MILLER_MAX_NODES = 262145, MILLER_CONTOUR_NODES = 4097 };
+
+struct gkyl_gen_miller_eqdsk {
+  struct gkyl_gen_miller_eqdsk_inp inp;
+  struct gkyl_gen_miller_eqdsk_info info;
+  double eta, fpol, s_guard;
+  double *s, *g, *slope, *flux, *mid, *new_s, *new_g, *new_mid;
+  double *psi_rz, *qpsi, *guard;
+  bool sampled;
+};
+
+// Test IEEE binary64 exponents explicitly, including builds using -ffast-math.
+static bool
+gen_miller_finite(double value)
+{
+  uint64_t bits;
+  memcpy(&bits, &value, sizeof bits);
+  return (bits & UINT64_C(0x7ff0000000000000)) != UINT64_C(0x7ff0000000000000);
+}
+
+static bool
+gen_miller_error(char *error, size_t size, const char *message)
+{
+  if (error && size) snprintf(error, size, "%s", message);
+  return false;
+}
+
+static double
+gen_miller_omp(const gkyl_gen_miller_eqdsk *up, double radius)
+{
+  return up->inp.r_axis-up->inp.a_shift*radius*radius/(2*up->inp.r_axis)+radius;
+}
+
+static double
+gen_miller_radius(const gkyl_gen_miller_eqdsk *up, double r_omp)
+{
+  double offset = r_omp-up->inp.r_axis;
+  double disc = 1-2*up->inp.a_shift*offset/up->inp.r_axis;
+  if (!gen_miller_finite(offset) || offset < 0 || disc <= 0) return NAN;
+  return 2*offset/(1+sqrt(disc));
+}
+
+void
+gkyl_gen_miller_eqdsk_surface(const gkyl_gen_miller_eqdsk *up, double radius, double theta, double rz[2])
+{
+  rz[0] = up->inp.r_axis-up->inp.a_shift*radius*radius/(2*up->inp.r_axis)
+    + radius*cos(theta+up->eta*sin(theta));
+  rz[1] = up->inp.z_axis+up->inp.kappa*radius*sin(theta);
+}
+
+static double
+gen_miller_det_over_r(const gkyl_gen_miller_eqdsk *up, double radius, double theta)
+{
+  double sint = sin(theta), cost = cos(theta), angle = theta+up->eta*sint;
+  return up->inp.kappa*((cos(angle)-up->inp.a_shift*radius/up->inp.r_axis)*cost
+    + (1+up->eta*cost)*sin(angle)*sint);
+}
+
+static double
+gen_miller_q(const gkyl_gen_miller_eqdsk *up, double radius)
+{
+  return up->inp.qprofile(gen_miller_omp(up, radius), up->inp.qctx);
+}
+
+// Periodic trapezoidal refinement is spectrally convergent for this smooth
+// angular integrand. It avoids the loose stopping threshold of gkyl_dbl_exp.
+static double
+gen_miller_flux_derivative(const gkyl_gen_miller_eqdsk *up, double s)
+{
+  double radius = sqrt(s), q = gen_miller_q(up, radius), previous = 0;
+  if (!gen_miller_finite(q) || q <= 0) return NAN;
+  for (int count = 32; count <= 16384; count *= 2) {
+    double sum = 0;
+    for (int j = 0; j < count; ++j) {
+      double theta = 2*M_PI*j/count, rz[2];
+      gkyl_gen_miller_eqdsk_surface(up, radius, theta, rz);
+      double det = gen_miller_det_over_r(up, radius, theta);
+      if (rz[0] <= 0 || det <= 0) return NAN;
+      sum += up->inp.r_axis*det/rz[0];
+    }
+    double integral = sum*2*M_PI/count;
+    if (count > 32 && fabs(integral-previous) <= up->inp.rtol*0.05*fmax(1, fabs(integral)))
+      return up->fpol*integral/(4*M_PI*up->inp.r_axis*q);
+    previous = integral;
+  }
+  return NAN;
+}
+
+static double
+gen_miller_endpoint_slope(double h0, double h1, double m0, double m1)
+{
+  double result = ((2*h0+h1)*m0-h0*m1)/(h0+h1);
+  if (result*m0 <= 0) return 0;
+  if (m0*m1 <= 0 && fabs(result) > fabs(3*m0)) return 3*m0;
+  return result;
+}
+
+static void
+gen_miller_slopes(gkyl_gen_miller_eqdsk *up)
+{
+  int count = up->info.radial_nodes;
+  for (int j = 1; j < count-1; ++j) {
+    double h0 = up->s[j]-up->s[j-1], h1 = up->s[j+1]-up->s[j];
+    double m0 = (up->g[j]-up->g[j-1])/h0, m1 = (up->g[j+1]-up->g[j])/h1;
+    double w0 = 2*h1+h0, w1 = h1+2*h0;
+    up->slope[j] = m0*m1 <= 0 ? 0 : (w0+w1)/(w0/m0+w1/m1);
+  }
+  double h0 = up->s[1]-up->s[0], h1 = up->s[2]-up->s[1];
+  up->slope[0] = gen_miller_endpoint_slope(h0, h1, (up->g[1]-up->g[0])/h0, (up->g[2]-up->g[1])/h1);
+  h0 = up->s[count-1]-up->s[count-2];
+  h1 = up->s[count-2]-up->s[count-3];
+  up->slope[count-1] = gen_miller_endpoint_slope(h0, h1,
+    (up->g[count-1]-up->g[count-2])/h0, (up->g[count-2]-up->g[count-3])/h1);
+}
+
+static double
+gen_miller_midpoint(const gkyl_gen_miller_eqdsk *up, int index)
+{
+  return 0.5*(up->g[index]+up->g[index+1])
+    +(up->s[index+1]-up->s[index])*(up->slope[index]-up->slope[index+1])/8;
+}
+
+static double
+gen_miller_integral(const gkyl_gen_miller_eqdsk *up, int index, double x)
+{
+  double h = up->s[index+1]-up->s[index], t = x/h;
+  double left = up->g[index], right = up->g[index+1];
+  double dl = up->slope[index]*h, dr = up->slope[index+1]*h;
+  double a2 = 3*(right-left)-2*dl-dr, a3 = 2*(left-right)+dl+dr;
+  return h*t*(left+t*(dl/2+t*(a2/3+t*a3/4)));
+}
+
+static bool
+gen_miller_build_table(gkyl_gen_miller_eqdsk *up)
+{
+  up->info.radial_nodes = 65;
+  for (int j = 0; j < 65; ++j) {
+    up->s[j] = up->s_guard*pow(j/64.0, 4);
+    up->g[j] = gen_miller_flux_derivative(up, up->s[j]);
+    up->mid[j] = -1;
+    if (!gen_miller_finite(up->g[j]) || up->g[j] <= 0) return false;
+  }
+  for (int pass = 0; pass < 120; ++pass) {
+    gen_miller_slopes(up);
+    int count = up->info.radial_nodes, next = 0;
+    double gmax = 0, error = 0;
+    for (int j = 0; j < count; ++j) gmax = fmax(gmax, up->g[j]);
+    for (int j = 0; j < count-1; ++j) {
+      double middle = 0.5*(up->s[j]+up->s[j+1]);
+      if (up->mid[j] <= 0) up->mid[j] = gen_miller_flux_derivative(up, middle);
+      if (!gen_miller_finite(up->mid[j]) || up->mid[j] <= 0) return false;
+      double relative = fabs(gen_miller_midpoint(up, j)-up->mid[j])/fmax(up->mid[j], gmax*1e-8);
+      error = fmax(error, relative);
+      if (next+3 >= MILLER_MAX_NODES) return false;
+      up->new_s[next] = up->s[j];
+      up->new_g[next] = up->g[j];
+      up->new_mid[next++] = relative > up->inp.rtol ? -1 : up->mid[j];
+      if (relative > up->inp.rtol) {
+        up->new_s[next] = middle;
+        up->new_g[next] = up->mid[j];
+        up->new_mid[next++] = -1;
+      }
+    }
+    if (next == count-1) {
+      up->info.radial_error = error;
+      up->flux[0] = 0;
+      for (int j = 0; j < count-1; ++j)
+        up->flux[j+1] = up->flux[j]+gen_miller_integral(up, j, up->s[j+1]-up->s[j]);
+      up->info.psi_guard = up->flux[count-1];
+      return true;
+    }
+    up->new_s[next] = up->s[count-1];
+    up->new_g[next] = up->g[count-1];
+    up->new_mid[next++] = -1;
+    memcpy(up->s, up->new_s, next*sizeof(double));
+    memcpy(up->g, up->new_g, next*sizeof(double));
+    memcpy(up->mid, up->new_mid, next*sizeof(double));
+    up->info.radial_nodes = next;
+  }
+  return false;
+}
+
+static double
+gen_miller_psi_s(const gkyl_gen_miller_eqdsk *up, double s)
+{
+  int lo = 0, hi = up->info.radial_nodes-1;
+  if (s >= up->s_guard) return up->info.psi_guard+up->g[hi]*(s-up->s_guard);
+  while (hi-lo > 1) {
+    int middle = (lo+hi)/2;
+    if (up->s[middle] <= s) lo = middle;
+    else hi = middle;
+  }
+  return up->flux[lo]+gen_miller_integral(up, lo, s-up->s[lo]);
+}
+
+double
+gkyl_gen_miller_eqdsk_psi_from_omp(const gkyl_gen_miller_eqdsk *up, double r_omp)
+{
+  double radius = gen_miller_radius(up, r_omp);
+  if (!gen_miller_finite(radius) || radius > up->info.r_guard*(1+4*DBL_EPSILON)) return NAN;
+  return gen_miller_psi_s(up, radius*radius);
+}
+
+double
+gkyl_gen_miller_eqdsk_omp_from_psi(const gkyl_gen_miller_eqdsk *up, double psi)
+{
+  if (!gen_miller_finite(psi) || psi < 0 || psi > up->info.psi_guard) return NAN;
+  if (psi == 0) return up->inp.r_axis;
+  double lo = 0, hi = up->s_guard;
+  for (int iter = 0; iter < 52; ++iter) {
+    double middle = (lo+hi)/2;
+    if (gen_miller_psi_s(up, middle) < psi) lo = middle;
+    else hi = middle;
+  }
+  return gen_miller_omp(up, sqrt((lo+hi)/2));
+}
+
+const struct gkyl_gen_miller_eqdsk_info *
+gkyl_gen_miller_eqdsk_get_info(const gkyl_gen_miller_eqdsk *up)
+{
+  return &up->info;
+}
+
+void
+gkyl_gen_miller_eqdsk_release(gkyl_gen_miller_eqdsk *up)
+{
+  if (!up) return;
+  gkyl_free(up->s); gkyl_free(up->g); gkyl_free(up->slope); gkyl_free(up->flux);
+  gkyl_free(up->mid); gkyl_free(up->new_s); gkyl_free(up->new_g); gkyl_free(up->new_mid);
+  gkyl_free(up->psi_rz); gkyl_free(up->qpsi); gkyl_free(up->guard);
+  gkyl_free(up);
+}
+
+gkyl_gen_miller_eqdsk *
+gkyl_gen_miller_eqdsk_inew(const struct gkyl_gen_miller_eqdsk_inp *inp, char *error, size_t error_size)
+{
+  if (!inp || !inp->qprofile) {
+    gen_miller_error(error, error_size, "Miller geometry requires a qprofile callback");
+    return 0;
+  }
+  gkyl_gen_miller_eqdsk *up = gkyl_calloc(1, sizeof *up);
+  up->inp = *inp;
+  if (up->inp.kappa == 0) up->inp.kappa = 1;
+  if (up->inp.rtol == 0) up->inp.rtol = 1e-10;
+  if (up->inp.guard_fraction == 0) up->inp.guard_fraction = 0.05;
+  if (up->inp.nr == 0) up->inp.nr = 257;
+  if (up->inp.nz == 0) up->inp.nz = 257;
+  double params[] = {inp->r_axis, inp->z_axis, inp->b_axis, inp->r_lcfs, up->inp.kappa,
+    inp->delta, inp->a_shift, up->inp.rtol, up->inp.guard_fraction};
+  bool valid = true;
+  for (int j = 0; j < sizeof params/sizeof params[0]; ++j) valid = valid && gen_miller_finite(params[j]);
+  if (!valid || inp->r_axis <= 0 || inp->b_axis <= 0 || inp->r_lcfs <= inp->r_axis ||
+      up->inp.kappa <= 0 || fabs(inp->delta) >= 1 || up->inp.rtol < 1e-13 || up->inp.rtol > 1e-3 ||
+      up->inp.guard_fraction <= 0 || up->inp.nr < 5 || up->inp.nz < 5 ||
+      up->inp.nr > 999 || up->inp.nz > 999 || up->inp.nr%2 == 0 || up->inp.nz%2 == 0) {
+    gen_miller_error(error, error_size, "Invalid Miller parameters or odd R-Z node counts (5..999)");
+    goto fail;
+  }
+  up->eta = asin(inp->delta);
+  up->fpol = inp->r_axis*inp->b_axis;
+  up->info.nr = up->inp.nr; up->info.nz = up->inp.nz;
+  up->info.r_lcfs = gen_miller_radius(up, inp->r_lcfs);
+  up->info.r_required = up->info.r_lcfs;
+  if (inp->has_omp_bounds) {
+    double lower = gen_miller_radius(up, inp->omp_bounds[0]);
+    double upper = gen_miller_radius(up, inp->omp_bounds[1]);
+    if (!gen_miller_finite(lower) || !gen_miller_finite(upper) || lower >= upper) {
+      gen_miller_error(error, error_size, "Invalid outboard midplane coverage bounds");
+      goto fail;
+    }
+    up->info.r_required = fmax(up->info.r_required, upper);
+  }
+  up->info.r_guard = up->info.r_required*(1+up->inp.guard_fraction);
+  up->s_guard = up->info.r_guard*up->info.r_guard;
+  if (!gen_miller_finite(up->s_guard) || up->info.r_guard <= 0) {
+    gen_miller_error(error, error_size, "LCFS or guard exceeds the increasing midplane branch");
+    goto fail;
+  }
+  for (int ir = 0; ir <= 256; ++ir) {
+    double radius = up->info.r_guard*ir/256, q = gen_miller_q(up, radius);
+    if (!gen_miller_finite(q) || q <= 0 || 1-inp->a_shift*radius/inp->r_axis <= 0) {
+      gen_miller_error(error, error_size, "Nonpositive/nonfinite q or folded midplane map before guard");
+      goto fail;
+    }
+    for (int it = 0; it <= 1024; ++it) {
+      double theta = 2*M_PI*it/1024, rz[2];
+      gkyl_gen_miller_eqdsk_surface(up, radius, theta, rz);
+      if (rz[0] <= 0 || gen_miller_det_over_r(up, radius, theta) <= 0) {
+        gen_miller_error(error, error_size, "Physical Miller surfaces fold or cross R=0");
+        goto fail;
+      }
+    }
+  }
+  size_t bytes = MILLER_MAX_NODES*sizeof(double);
+  up->s = gkyl_malloc(bytes); up->g = gkyl_malloc(bytes); up->slope = gkyl_malloc(bytes);
+  up->flux = gkyl_malloc(bytes); up->mid = gkyl_malloc(bytes); up->new_s = gkyl_malloc(bytes);
+  up->new_g = gkyl_malloc(bytes); up->new_mid = gkyl_malloc(bytes);
+  up->psi_rz = gkyl_malloc((size_t)up->info.nr*up->info.nz*sizeof(double));
+  up->qpsi = gkyl_malloc(up->info.nr*sizeof(double));
+  up->guard = gkyl_malloc(2*MILLER_CONTOUR_NODES*sizeof(double));
+  if (!gen_miller_build_table(up)) {
+    gen_miller_error(error, error_size, "Miller flux quadrature/interpolation failed; check q and rtol");
+    goto fail;
+  }
+  up->info.psi_boundary = gen_miller_psi_s(up, up->info.r_lcfs*up->info.r_lcfs);
+  double bounds[] = {DBL_MAX, -DBL_MAX, DBL_MAX, -DBL_MAX};
+  for (int j = 0; j < MILLER_CONTOUR_NODES; ++j) {
+    double *rz = up->guard+2*j;
+    gkyl_gen_miller_eqdsk_surface(up, up->info.r_guard, 2*M_PI*j/(MILLER_CONTOUR_NODES-1), rz);
+    bounds[0] = fmin(bounds[0], rz[0]); bounds[1] = fmax(bounds[1], rz[0]);
+    bounds[2] = fmin(bounds[2], rz[1]); bounds[3] = fmax(bounds[3], rz[1]);
+  }
+  double rpad = 0.02*(bounds[1]-bounds[0]), zpad = 0.02*(bounds[3]-bounds[2]);
+  bounds[0] -= rpad; bounds[1] += rpad; bounds[2] -= zpad; bounds[3] += zpad;
