+    snprintf(error, sizeof error, "Miller coverage bounds do not include the simulation");
+    failure = 1;
+  }
+  if (!inp.has_omp_bounds) {
+    inp.has_omp_bounds = true;
+    inp.omp_bounds[0] = gk->lower[0];
+    inp.omp_bounds[1] = gk->upper[0];
+  }
+  gkyl_gen_miller_eqdsk *generator = failure ? 0 : gkyl_gen_miller_eqdsk_inew(&inp, error, sizeof error);
+  if (!generator) failure = 1;
+  if (comm) gkyl_comm_allreduce_host(comm, GKYL_INT, GKYL_MAX, 1, &failure, &global_failure);
+  else global_failure = failure;
+  if (global_failure) {
+    if (failure) fprintf(stderr, "Miller initialization (rank %d): %s\n", rank, error);
+    gkyl_gen_miller_eqdsk_release(generator);
+    return false;
+  }
+  const struct gkyl_gen_miller_eqdsk_info *info = gkyl_gen_miller_eqdsk_get_info(generator);
+  double psi_lower = gkyl_gen_miller_eqdsk_psi_from_omp(generator, gk->lower[0]);
+  double psi_upper = gkyl_gen_miller_eqdsk_psi_from_omp(generator, gk->upper[0]);
+  bool crossing = gk->lower[0] < inp.r_lcfs && gk->upper[0] > inp.r_lcfs;
